mapper.select:
SELECT c.id, c.spu_id, c.sku_id, c.order_id, c.order_no, c.member_id, c.member_name, c.member_avatar, c.rating, c.content, c.is_anonymous, c.is_replied, c.reply_content, c.reply_time, c.status, c.create_time, c.images, s.name AS spu_name, s.pic_url AS spu_pic, sk.name AS sku_name FROM pms_goods_comment c LEFT JOIN pms_spu s ON c.spu_id = s.id LEFT JOIN pms_sku sk ON c.sku_id = sk.id WHERE c.deleted = 0
AND s.name LIKE CONCAT('%', #{query.spuName}, '%')
AND c.status = #{query.status}
AND c.rating = #{query.rating}
AND c.create_time >= #{query.startTime}
AND c.create_time <= #{query.endTime}
ORDER BY c.create_time DESC

mapper.update:
UPDATE oms_order_item
SET is_commented = 1, update_time = NOW()
WHERE id = #{orderItemId}
